//! The git DRIVERS for the record store — `bsc graph driver {textconv,merge,install}`.
//!
//! ── WHAT GIT ALREADY DOES, AND THE ONE THING IT CANNOT ──────────────────────────────────────────
//! Git is a mature surface and we take it rather than rebuild it: branches, three-way merges, blame,
//! bisect, review all work already. What git cannot do is read a record, because a record's whole
//! module body is ONE LINE of JSON — measured across `graph/records/`, a file is 11-27 lines but
//! 23-37 KILOBYTES. Every line-oriented thing git offers degrades to uselessness on that shape:
//!
//!   * `git diff` prints the entire before and after body as two enormous lines;
//!   * `git blame` resolves every line of a module to whichever commit last touched `code`;
//!   * a merge of two edits to DIFFERENT functions in one module is a conflict over 23 KB of
//!     unsplittable text, which nobody resolves by hand.
//!
//! Splitting the store into one file per record fixed merging BETWEEN records and did nothing for
//! WITHIN one. These drivers are that missing half, and they are the reason the store can move to a
//! database later without losing history: git keeps doing the coordination, taught to speak record.
//!
//! ── TEXTCONV IS FOR READING, MERGE IS FOR WRITING ───────────────────────────────────────────────
//! `textconv` renders a record as its SOURCE, so `git diff`/`show`/`blame` operate on real lines. It
//! is deliberately lossy-safe: git never writes textconv output back, so it exists purely to be read.
//! `merge` is the opposite — its output IS the file — so it preserves every field and marks what it
//! could not resolve rather than choosing.

/// Render a record file as readable text for `git diff`/`show`/`blame`.
///
/// The header carries the fields a reviewer needs to see change (a renamed record, a moved feature, a
/// changed `provides` are all real edits), then the body as real lines. Non-code fields are rendered
/// one per line for the same reason the body is: so a diff of them is a diff of lines.
pub fn textconv(path: &std::path::Path) -> Result<String, String> {
    let raw = std::fs::read_to_string(path)
        .map_err(|e| format!("cannot read {} for textconv: {e}", path.display()))?;
    // A git textconv must NEVER fail the command it is decorating: `git log -p` over a range that
    // predates the store would abort on the first unparseable blob. Anything we cannot read is passed
    // through unchanged, which is exactly what git would have shown without a driver.
    let rec: serde_json::Value = match serde_json::from_str(&raw) {
        Ok(v) => v,
        Err(_) => return Ok(raw),
    };
    let obj = match rec.as_object() {
        Some(o) => o,
        None => return Ok(raw),
    };

    let mut out = String::new();
    for key in ["id", "name", "tech", "role", "feature", "domain", "src", "folder", "provides", "moduleVis"] {
        if let Some(v) = obj.get(key).and_then(|v| v.as_str()) {
            out.push_str(&format!("{key}: {v}\n"));
        }
    }
    for key in ["composes", "tags", "crateDeps", "imports", "moduleState", "requiredBy"] {
        if let Some(a) = obj.get(key).and_then(|v| v.as_array()) {
            if a.is_empty() {
                continue;
            }
            // ONE PER LINE, not a joined list: adding a single dependency should diff as one added
            // line, not as a rewrite of the whole set.
            out.push_str(&format!("{key}:\n"));
            for e in a {
                out.push_str(&format!("  - {}\n", e.as_str().unwrap_or("")));
            }
        }
    }
    for (label, key) in [("code", "code"), ("tests", "tests")] {
        if let Some(s) = obj.get(key).and_then(|v| v.as_str()) {
            if s.is_empty() {
                continue;
            }
            out.push_str(&format!("\n--- {label} ---\n"));
            out.push_str(s);
            if !s.ends_with('\n') {
                out.push('\n');
            }
        }
    }
    Ok(out)
}

/// Merge one record three ways. Returns the merged JSON and how many fields conflicted.
///
/// FIELD BY FIELD, because that is what a record is. Two sessions that touched different fields have
/// not conflicted at all, and today git calls that a conflict because both edits land on one line.
/// `code` and `tests` are TEXT, so they go through the three-way line merge and come back as an ordinary source
/// merge; lists are unioned in order; anything else that both sides changed differently is a genuine
/// conflict this must not paper over.
pub fn merge_record(
    base: &str,
    ours: &str,
    theirs: &str,
    labels: (&str, &str),
    marker: usize,
) -> Result<(String, usize), String> {
    let p = |what: &str, s: &str| -> Result<serde_json::Map<String, serde_json::Value>, String> {
        serde_json::from_str::<serde_json::Value>(s)
            .map_err(|e| format!("the {what} side is not valid JSON: {e}"))?
            .as_object()
            .cloned()
            .ok_or_else(|| format!("the {what} side is not a JSON object"))
    };
    let (b, o, t) = (p("base", base)?, p("ours", ours)?, p("theirs", theirs)?);

    let mut keys: Vec<String> = b.keys().chain(o.keys()).chain(t.keys()).cloned().collect();
    keys.sort();
    keys.dedup();

    let mut out = serde_json::Map::new();
    let mut conflicts = 0usize;
    for k in keys {
        let (bv, ov, tv) = (b.get(&k), o.get(&k), t.get(&k));
        // Unchanged on one side is the other side's edit — including a DELETION, which is why this
        // compares Options rather than values.
        if ov == tv {
            if let Some(v) = ov {
                out.insert(k, v.clone());
            }
            continue;
        }
        if bv == ov {
            if let Some(v) = tv {
                out.insert(k, v.clone());
            }
            continue;
        }
        if bv == tv {
            if let Some(v) = ov {
                out.insert(k, v.clone());
            }
            continue;
        }
        // Both changed it, differently.
        let text = |v: Option<&serde_json::Value>| v.and_then(|v| v.as_str()).unwrap_or("").to_string();
        if k == "code" || k == "tests" {
            let m = crate::merge3::merge3(&text(bv), &text(ov), &text(tv), labels, marker);
            conflicts += m.conflicts;
            out.insert(k, serde_json::Value::String(m.text));
            continue;
        }
        if let (Some(oa), Some(ta)) = (ov.and_then(|v| v.as_array()), tv.and_then(|v| v.as_array())) {
            // A UNION, in order, first-seen wins. Two sessions adding different dependencies both
            // added one; taking a side would silently drop the other's.
            let mut merged: Vec<serde_json::Value> = Vec::new();
            for v in oa.iter().chain(ta.iter()) {
                if !merged.contains(v) {
                    merged.push(v.clone());
                }
            }
            out.insert(k, serde_json::Value::Array(merged));
            continue;
        }
        // A scalar both sides moved differently. There is no honest resolution, so it is REPORTED —
        // the value keeps ours and the conflict count is what makes git leave the file for a human.
        conflicts += 1;
        out.insert(k.clone(), ov.cloned().unwrap_or(serde_json::Value::Null));
        out.insert(
            format!("{k}__conflict"),
            serde_json::json!({ "ours": ov, "theirs": tv, "base": bv }),
        );
    }
    let text = serde_json::to_string_pretty(&serde_json::Value::Object(out))
        .map_err(|e| format!("cannot serialize the merged record: {e}"))?;
    Ok((format!("{text}\n"), conflicts))
}

/// Register the drivers in THIS clone, and declare them on the store.
///
/// `.gitattributes` can NAME a driver but cannot define one — the definition is local config, by
/// design, because a repo that could hand you a command to run would be a repo that could run
/// anything on clone. So this is an explicit install, the same shape as `bsc app hooks`.
pub fn install(repo: &std::path::Path, bsc: &str) -> Result<String, String> {
    let ga = repo.join(".gitattributes");
    let want = [
        "# Record store — git speaks record through `bsc graph driver` (retire-the-committed-json-record-store).",
        "# `merge=bscrecord` merges FIELD BY FIELD and runs `code` through a real three-way line merge,",
        "# so two sessions editing different functions of one module no longer collide on its single",
        "# JSON line. `diff=bscrecord` renders the body as source, so diff/show/blame see real lines.",
        "graph/records/*.json merge=bscrecord diff=bscrecord",
        "graph/algorithms.json diff=bscrecord",
    ];
    let existing = std::fs::read_to_string(&ga).unwrap_or_default();
    if !existing.contains("merge=bscrecord") {
        let mut next = existing.clone();
        if !next.is_empty() && !next.ends_with('\n') {
            next.push('\n');
        }
        if !next.is_empty() {
            next.push('\n');
        }
        next.push_str(&want.join("\n"));
        next.push('\n');
        std::fs::write(&ga, next).map_err(|e| format!("cannot write {}: {e}", ga.display()))?;
    }

    // A HANDSHAKE BEFORE THE REGISTRATION, because a path is not a capability.
    //
    // Registering a `bsc` that does not answer `graph driver` does not fail loudly — it makes the
    // binary print its HELP into git's textconv stream, so `git diff` on any record renders a help
    // screen and exits non-zero. MEASURED here by doing exactly that: the staged sidecar predated the
    // verb, and one `install` broke `git diff` for every worktree in the clone at once, because
    // `.git/config` is shared. Ask the binary whether it can do the job before telling git it can.
    {
        let probe = std::env::temp_dir().join(format!("bsc-driver-probe-{}.json", std::process::id()));
        std::fs::write(&probe, "{\"id\":\"probe\",\"code\":\"ok\\n\"}")
            .map_err(|e| format!("cannot write the probe file: {e}"))?;
        let out = std::process::Command::new(bsc)
            .args(["graph", "driver", "textconv"])
            .arg(&probe)
            .output();
        std::fs::remove_file(&probe).ok();
        let out = out.map_err(|e| format!("cannot run {bsc}: {e}"))?;
        let said = String::from_utf8_lossy(&out.stdout);
        if !out.status.success() || !said.contains("id: probe") {
            return Err(format!(
                "{bsc} does not answer `graph driver textconv`, so registering it would make \
                 `git diff` on every record print an error instead of a diff — and `.git/config` is \
                 SHARED, so that breaks every worktree at once. Stage a current sidecar \
                 (`npm run build:plan`) and re-run. Nothing was written."
            ));
        }
    }

    // Local config, per clone. `%O %A %B %L %P` is git's own contract: base, ours (which the driver
    // MUST overwrite with the result), theirs, the conflict-marker size, and the real pathname.
    let cfg = [
        ("merge.bscrecord.name", "record-aware three-way merge".to_string()),
        ("merge.bscrecord.driver", format!("{bsc} graph driver merge %O %A %B %L %P")),
        ("diff.bscrecord.textconv", format!("{bsc} graph driver textconv")),
        // Without this, `git diff` caches textconv output keyed only by blob — correct, and worth
        // having, because rendering 2,944 records repeatedly is the difference between instant and not.
        ("diff.bscrecord.cachetextconv", "true".to_string()),
    ];
    for (k, v) in &cfg {
        let out = std::process::Command::new("git")
            .arg("-C")
            .arg(repo)
            .args(["config", "--local", k, v])
            .output()
            .map_err(|e| format!("cannot run git config: {e}"))?;
        if !out.status.success() {
            return Err(format!(
                "git config --local {k} failed: {}",
                String::from_utf8_lossy(&out.stderr).trim()
            ));
        }
    }
    Ok(format!(
        "registered `bscrecord` in {} — merge driver + textconv, and .gitattributes declares them.\n\
         A clone that has not run this still WORKS: git falls back to its line merge, which is what \
         you have today.",
        repo.display()
    ))
}

/// `bsc graph driver <textconv|merge|install>` — the three git calls, and nothing else.
///
/// Shaped for GIT to call, not for a person: `merge` takes git's own `%O %A %B %L %P` in that order
/// and overwrites `%A` in place, because that is the contract a merge driver has. A non-zero exit is
/// how a driver says "conflicts remain", so an unresolved region returns Err rather than printing a
/// warning and succeeding — a merge driver that exits 0 on conflict silently commits one side.
pub fn cmd(positional: &[&str], _args: &[String]) -> Result<(), String> {
    match positional.get(1).copied().unwrap_or("") {
        "textconv" => {
            let p = positional
                .get(2)
                .ok_or("usage: bsc graph driver textconv <file> — git passes the path")?;
            print!("{}", textconv(std::path::Path::new(p))?);
            Ok(())
        }
        "merge" => {
            let need = |i: usize, what: &str| {
                positional
                    .get(i)
                    .copied()
                    .ok_or_else(|| format!("usage: bsc graph driver merge %O %A %B %L %P — missing {what}"))
            };
            let (base, ours, theirs) = (need(2, "%O (base)")?, need(3, "%A (ours)")?, need(4, "%B (theirs)")?);
            let marker: usize = positional.get(5).and_then(|s| s.parse().ok()).unwrap_or(7);
            let path = positional.get(6).copied().unwrap_or(ours);
            let read = |p: &str| {
                std::fs::read_to_string(p).map_err(|e| format!("cannot read {p} for the merge: {e}"))
            };
            let (b, o, t) = (read(base)?, read(ours)?, read(theirs)?);
            let (merged, conflicts) = merge_record(&b, &o, &t, ("ours", "theirs"), marker)?;
            // `%A` IS the output file. Writing anywhere else leaves git with the unmerged side and no
            // indication anything happened.
            std::fs::write(ours, &merged).map_err(|e| format!("cannot write the merge result to {ours}: {e}"))?;
            if conflicts > 0 {
                return Err(format!(
                    "{path}: {conflicts} conflict(s) left in the record — resolve them and \
                     `git add` it. `git diff` renders the body as source through the textconv driver."
                ));
            }
            Ok(())
        }
        "install" => {
            let repo = std::env::current_dir().map_err(|e| format!("cannot read the cwd: {e}"))?;
            let bsc = stable_bsc_path()?;
            println!("{}", install(&repo, &bsc)?);
            Ok(())
        }
        other => Err(format!(
            "unknown `bsc graph driver` command {other:?} — textconv | merge | install. These are \
             GIT's entry points, registered by `install`; you do not normally call them by hand."
        )),
    }
}

/// A STABLE path to `bsc` for git to call — never one under `target/`.
///
/// This is written into `.git/config` and lives longer than any build. A `target/debug/bsc` is swept
/// by `bsc disk gc`, removed with the worktree by `bsc worktree cap`, and — the dangerous one —
/// ZEROED by `cargo clippy --workspace --all-targets`. A zero-byte file executed through a shell is an
/// empty script that exits 0 printing NOTHING, so git would render every record as an empty diff and
/// report success. That is the silent-wrong outcome this whole store keeps getting caught by, so the
/// path is resolved to the staged sidecar and a `target/` path is REFUSED rather than warned about.
fn stable_bsc_path() -> Result<String, String> {
    if let Ok(v) = std::env::var("BSC_BIN") {
        let v = v.trim().to_string();
        if !v.is_empty() && !v.contains("/target/") {
            return Ok(v);
        }
    }
    if let Some(home) = std::env::var_os("HOME") {
        let staged = std::path::Path::new(&home).join(".base-studio-code/bin/bsc");
        if staged.is_file() {
            return Ok(staged.display().to_string());
        }
    }
    if let Ok(exe) = std::env::current_exe() {
        let p = exe.display().to_string();
        if !p.contains("/target/") {
            return Ok(p);
        }
        return Err(format!(
            "refusing to register {p} as the git driver: it is a build artifact. `target/debug/bsc` is \
             swept by `bsc disk gc`, removed by `bsc worktree cap`, and ZEROED by \
             `cargo clippy --all-targets` — and a zero-byte binary exits 0 printing nothing, so git \
             would render every record as an empty diff and call it success. Stage a sidecar \
             (`npm run build:plan`) or set BSC_BIN to a stable path, then re-run."
        ));
    }
    Err("cannot resolve a stable `bsc` path for the git driver — set BSC_BIN".to_string())
}

#[cfg(test)]
mod driver_tests {
    use super::*;

    fn rec(code: &str, extra: &str) -> String {
        format!("{{\"id\":\"x.rs\",\"name\":\"x\",\"tech\":\"rust\",\"code\":{},\"composes\":[{extra}]}}",
                serde_json::Value::String(code.to_string()))
    }

    /// THE CASE THE DRIVER EXISTS FOR. Two sessions edit different functions of one module. Git's line
    /// merge sees one changed line — the whole 23 KB body — and conflicts. This must not.
    #[test]
    fn two_edits_to_different_functions_of_one_record_merge_clean() {
        let base = rec("fn a() {}\nfn b() {}\nfn c() {}\n", "");
        let ours = rec("fn a() { 1 }\nfn b() {}\nfn c() {}\n", "");
        let theirs = rec("fn a() {}\nfn b() {}\nfn c() { 3 }\n", "");
        let (out, conflicts) = merge_record(&base, &ours, &theirs, ("ours", "theirs"), 7).expect("merge");
        assert_eq!(conflicts, 0, "disjoint edits are not a conflict:\n{out}");
        let v: serde_json::Value = serde_json::from_str(&out).expect("valid JSON out");
        let code = v["code"].as_str().expect("code");
        assert!(code.contains("fn a() { 1 }"), "ours survived: {code}");
        assert!(code.contains("fn c() { 3 }"), "theirs survived: {code}");
    }

    /// The same function edited two ways is a REAL conflict, and must be reported rather than resolved.
    #[test]
    fn the_same_function_edited_two_ways_is_reported() {
        let base = rec("fn a() {}\n", "");
        let ours = rec("fn a() { 1 }\n", "");
        let theirs = rec("fn a() { 2 }\n", "");
        let (out, conflicts) = merge_record(&base, &ours, &theirs, ("ours", "theirs"), 7).expect("merge");
        assert_eq!(conflicts, 1, "a real conflict is not silently resolved");
        let v: serde_json::Value = serde_json::from_str(&out).expect("still valid JSON");
        let code = v["code"].as_str().expect("code");
        assert!(code.contains("<<<<<<<") && code.contains(">>>>>>>"), "markers are in the body: {code}");
    }

    /// A field only ONE side touched is that side's edit, including when the other side changed a
    /// DIFFERENT field. Git cannot see this at all today.
    #[test]
    fn different_fields_are_not_a_conflict() {
        let base = "{\"id\":\"x.rs\",\"name\":\"x\",\"feature\":\"old\",\"code\":\"a\\n\"}".to_string();
        let ours = "{\"id\":\"x.rs\",\"name\":\"RENAMED\",\"feature\":\"old\",\"code\":\"a\\n\"}".to_string();
        let theirs = "{\"id\":\"x.rs\",\"name\":\"x\",\"feature\":\"NEW\",\"code\":\"a\\n\"}".to_string();
        let (out, conflicts) = merge_record(&base, &ours, &theirs, ("ours", "theirs"), 7).expect("merge");
        assert_eq!(conflicts, 0);
        let v: serde_json::Value = serde_json::from_str(&out).expect("valid");
        assert_eq!(v["name"], "RENAMED");
        assert_eq!(v["feature"], "NEW");
    }

    /// Lists UNION. Two sessions each adding a dependency both added one; taking a side drops work.
    #[test]
    fn list_fields_union_rather_than_taking_a_side() {
        let base = rec("a\n", "");
        let ours = rec("a\n", "\"one\"");
        let theirs = rec("a\n", "\"two\"");
        let (out, conflicts) = merge_record(&base, &ours, &theirs, ("ours", "theirs"), 7).expect("merge");
        assert_eq!(conflicts, 0);
        let v: serde_json::Value = serde_json::from_str(&out).expect("valid");
        let c: Vec<&str> = v["composes"].as_array().expect("array").iter().map(|x| x.as_str().unwrap_or("")).collect();
        assert!(c.contains(&"one") && c.contains(&"two"), "both survived: {c:?}");
    }

    #[test]
    fn textconv_renders_the_body_as_real_lines() {
        let dir = std::env::temp_dir().join(format!("bsc-textconv-{}", std::process::id()));
        std::fs::create_dir_all(&dir).expect("mkdir");
        let p = dir.join("r.json");
        std::fs::write(&p, rec("fn a() {}\nfn b() {}\n", "\"dep\"")).expect("write");
        let out = textconv(&p).expect("textconv");
        assert!(out.contains("id: x.rs"), "header carries the id:\n{out}");
        assert!(out.contains("  - dep"), "a list is one entry per line:\n{out}");
        assert!(out.contains("fn a() {}\nfn b() {}"), "the body is real lines:\n{out}");
        assert!(out.lines().count() > 4, "not one enormous line:\n{out}");
        std::fs::remove_dir_all(&dir).ok();
    }

    /// A textconv must NEVER fail the command it decorates — `git log -p` over a range predating the
    /// store would abort on the first unparseable blob.
    #[test]
    fn textconv_passes_through_anything_it_cannot_parse() {
        let dir = std::env::temp_dir().join(format!("bsc-textconv-bad-{}", std::process::id()));
        std::fs::create_dir_all(&dir).expect("mkdir");
        let p = dir.join("nope.json");
        std::fs::write(&p, "this is not json at all").expect("write");
        assert_eq!(textconv(&p).expect("must not fail"), "this is not json at all");
        std::fs::remove_dir_all(&dir).ok();
    }
}
